insert into public.assessment_questions(id,assessment_id,question,options,correct_answer,explanation,difficulty,skill_id,question_type) values ('66666666-6666-4666-8666-666666666661','55555555-5555-4555-8555-555555555555','Which clause filters rows before grouping?','["WHERE","HAVING","ORDER BY","LIMIT"]','WHERE','WHERE filters rows before grouping.','easy','11111111-1111-4111-8111-111111111111','mcq'),('66666666-6666-4666-8666-666666666662','55555555-5555-4555-8555-555555555555','Normalize this answer: the keyword for grouping rows is ____','[]','GROUP BY','GROUP BY groups rows for aggregation.','easy','11111111-1111-4111-8111-111111111111','fill_blank') on conflict (id) do update set question=excluded.question,options=excluded.options,correct_answer=excluded.correct_answer,explanation=excluded.explanation,question_type=excluded.question_type;
